<?php
namespace App\Http\Controllers;
use App\Models\{SalesInvoice,Contact,Account,Currency,TaxCode};use App\Services\SalesService;use Illuminate\Http\Request;
class SalesController {public function index(){return view('sales.index',['invoices'=>SalesInvoice::forCompany(auth()->user()->company_id)->with('contact')->latest('invoice_date')->paginate(50)]);}public function create(){return view('sales.create',$this->formData());}public function store(Request $r){$d=$r->validate(['contact_id'=>'required|integer','invoice_date'=>'required|date','due_date'=>'nullable|date','currency_id'=>'required|integer','exchange_rate'=>'required|decimal:1,10','lines'=>'required|array|min:1','lines.*.description'=>'required|string|max:1000','lines.*.quantity'=>'required|decimal:0,4','lines.*.unit_price'=>'required|decimal:0,6','lines.*.revenue_account_id'=>'required|integer','lines.*.tax_code_id'=>'nullable|integer']);$i=app(SalesService::class)->createDraft($r->user()->company_id,$r->user()->id,$d,$d['lines']);return redirect()->route('sales.show',$i);}public function show(SalesInvoice $invoice){return view('sales.show',['invoice'=>$invoice->load(['lines','contact','currency'])]);}public function post(SalesInvoice $invoice){app(SalesService::class)->post($invoice,auth()->id());return back()->with('ok','Invoice posted.');}public function credit(Request $r,SalesInvoice $invoice){$d=$r->validate(['invoice_date'=>'required|date','exchange_rate'=>'required|decimal:1,10','lines'=>'required|array|min:1','lines.*.description'=>'required|string|max:1000','lines.*.quantity'=>'required|decimal:0,4','lines.*.unit_price'=>'required|decimal:0,6','lines.*.revenue_account_id'=>'required|integer','lines.*.tax_code_id'=>'nullable|integer']);$c=app(SalesService::class)->createCredit($invoice,$r->user()->id,$d,$d['lines']);return redirect()->route('sales.show',$c)->with('ok','Credit draft created.');}private function formData():array{$c=auth()->user()->company_id;return ['contacts'=>Contact::forCompany($c)->whereIn('type',['customer','both'])->where('active',1)->orderBy('name')->get(),'accounts'=>Account::forCompany($c)->where('is_postable',1)->where('active',1)->whereIn('type',['revenue','income'])->orderBy('code')->get(),'currencies'=>Currency::where('active',1)->get(),'taxes'=>TaxCode::forCompany($c)->where('active',1)->whereIn('type',['sales','both'])->orderBy('code')->get()];}}
